# C++ 数据清洗与预处理代码

以下是使用C++实现的数据清洗与预处理代码，包括去重、缺失值处理、时间格式统一、文本标准化等功能：

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <cctype>
#include <locale>
#include <iomanip>
#include <regex>
#include <boost/algorithm/string.hpp>
#include <boost/date_time/posix_time/posix_time.hpp>
#include <boost/tokenizer.hpp>
#include <cmath>

using namespace std;
using namespace boost::posix_time;
using namespace boost::gregorian;

// 结构体定义：数据行
struct DataRow {
    map<string, string> fields;
};

// 1. 数据加载函数
vector<DataRow> loadData(const string& filePath, char delimiter = ',', const string& encoding = "UTF-8") {
    vector<DataRow> data;
    ifstream file(filePath);

    if (!file.is_open()) {
        cerr << "文件打开失败: " << filePath << endl;
        return data;
    }

    string line;
    while (getline(file, line)) {
        DataRow row;
        stringstream ss(line);
        string field;

        while (getline(ss, field, delimiter)) {
            // 处理字段中的空格
            if (!field.empty() && field[0] == ' ') {
                field.erase(0, 1);
            }
            row.fields[field] = field; // 简化版，实际应用中可能需要更复杂的处理
        }
        data.push_back(row);
    }

    return data;
}

// 2. 数据去重函数
vector<DataRow> removeDuplicates(const vector<DataRow>& data) {
    set<vector<string>> seen;
    vector<DataRow> uniqueData;

    for (const auto& row : data) {
        vector<string> rowVec;
        for (const auto& pair : row.fields) {
            rowVec.push_back(pair.second);
        }
        if (seen.find(rowVec) == seen.end()) {
            seen.insert(rowVec);
            uniqueData.push_back(row);
        }
    }

    return uniqueData;
}

// 3. 缺失值处理函数
vector<DataRow> handleMissingValues(vector<DataRow>& data, const string& strategy) {
    // 简化版：用空字符串填充缺失值
    for (auto& row : data) {
        for (auto& field : row.fields) {
            if (field.second.empty()) {
                if (strategy == "mean" || strategy == "median" || strategy == "mode") {
                    // 这里只是示例，实际实现需要根据数据类型处理
                    field.second = "0";
                } else if (strategy == "drop") {
                    row.fields.erase(field.first);
                }
            }
        }
    }
    return data;
}

// 4. 时间格式统一函数
vector<DataRow> standardizeDatetime(vector<DataRow>& data, const string& datetimeField) {
    // 简化版：假设时间格式为YYYY-MM-DD HH:MM:SS
    for (auto& row : data) {
        if (row.fields.find(datetimeField) != row.fields.end()) {
            string original = row[datetimeField];
            try {
                // 尝试解析标准格式
                time_input_iterator<char, char_separator<char>> tokens(original.begin(), original.end(), char_separator<char>());
                tokens++;
                string year = *tokens;
                tokens++;
                string month = *tokens;
                tokens++;
                string day = *tokens;
                tokens++;
                string hour = *tokens;
                tokens++;
                string minute = *tokens;
                tokens++;
                string second = *tokens;

                date d(
                    year_to_yd(stoi(year), stoi(month), stoi(day)),
                    stoj(month),
                    stoj(day)
                );

                time_period tp(
                    local_date_time(d, hours(stoi(hour)) + minutes(stoi(minute)) + seconds(stoi(second))),
                    local_date_time(d, hours(23) + minutes(59) + seconds(59))
                );

                // 将处理后的时间格式存储为字符串
                row[datetimeField] = year + "-" + month + "-" + day + " " + hour + ":" + minute + ":" + second;
            } catch (...) {
                // 如果解析失败，尝试其他方法
                try {
                    // 使用Boost.DateTime解析
                    local_date_time dt = from_iso_string(original);
                    ostringstream oss;
                    oss << dt;
                    row[datetimeField] = oss.str();
                } catch (...) {
                    // 解析失败，保留原始值
                    cout << "无法解析时间: " << original << endl;
                }
            }
        }
    }
    return data;
}

// 5. 文本标准化函数
vector<DataRow> textStandardization(vector<DataRow>& data, const string& textField) {
    // 简化版：只进行分词处理
    for (auto& row : data) {
        if (row.fields.find(textField) != row.fields.end()) {
            string text = row[textField];
            // 转换为小写
            for (char& c : text) {
                c = tolower(c);
            }
            // 去除特殊符号（简化版）
            text.erase(remove_if(text.begin(), text.end(), [](unsigned char c) {
                return !isalnum(c) && c != ' ';
            }), text.end());

            // 分词（使用空格分隔）
            boost::char_separator<char> cs(" ");
            boost::tokenizer<boost::char_separator<char>> tokens(text, cs);

            // 将分词结果组合成字符串（用空格分隔）
            string tokenized;
            for (const string& token : tokens) {
                if (!token.empty()) {
                    if (!tokenized.empty()) {
                        tokenized += " ";
                    }
                    tokenized += token;
                }
            }

            row[textField] = tokenized;
        }
    }
    return data;
}

// 6. 特征缩放函数
vector<DataRow> featureScaling(vector<DataRow>& data, const vector<string>& numericFields) {
    // 简化版：只对数值字段进行最小-最大缩放
    map<string, pair<double, double>> fieldRanges;

    // 收集每个字段的最小值和最大值
    for (auto& row : data) {
        for (const string& field : numericFields) {
            if (row.fields.find(field) != row.fields.end()) {
                try {
                    double value = stod(row[field]);
                    if (fieldRanges.find(field) == fieldRanges.end()) {
                        fieldRanges[field] = make_pair(value, value);
                    } else {
                        if (value < fieldRanges[field].first) {
                            fieldRanges[field].first = value;
                        }
                        if (value > fieldRanges[field].second) {
                            fieldRanges[field].second = value;
                        }
                    }
                } catch (...) {
                    // 转换失败，跳过
                    continue;
                }
            }
        }
    }

    // 应用最小-最大缩放
    for (auto& row : data) {
        for (const string& field : numericFields) {
            if (row.fields.find(field) != row.fields.end()) {
                try {
                    double value = stod(row[field]);
                    double minVal = fieldRanges[field].first;
                    double maxVal = fieldRanges[field].second;
                    double scaledValue = (value - minVal) / (maxVal - minVal);
                    row[field] = to_string(scaledValue);
                } catch (...) {
                    // 转换失败，保留原值
                    continue;
                }
            }
        }
    }

    return data;
}

// 辅助函数：获取map中的值
string& operator[](DataRow& row, const string& key) {
    return row.fields[key];
}

// 辅助函数：保存处理后的数据
bool saveProcessedData(const vector<DataRow>& data, const string& outputPath) {
    ofstream file(outputPath);
    if (!file.is_open()) {
        cerr << "无法打开文件保存: " << outputPath << endl;
        return false;
    }

    // 写入表头（简化版）
    if (!data.empty()) {
        file << "header1,header2,header3\n"; // 实际应用中应使用实际表头

        // 写入数据行
        for (const auto& row : data) {
            for (const auto& pair : row.fields) {
                file << "\"" << pair.second << "\",";
            }
            file << "\n";
        }
    }

    file.close();
    return true;
}

// 主函数：执行完整的数据预处理流程
vector<DataRow> dataPreprocessingPipeline(
    const string& filePath,
    char delimiter,
    const string& encoding,
    const string& datetimeColumn,
    const string& textField,
    const vector<string>& numericFields,
    const string& strategy
) {
    // 1. 加载数据
    vector<DataRow> data = loadData(filePath, delimiter, encoding);
    if (data.empty()) {
        return data;
    }

    // 2. 去重
    data = removeDuplicates(data);

    // 3. 处理缺失值
    data = handleMissingValues(data, strategy);

    // 4. 统一时间格式
    if (!datetimeColumn.empty()) {
        data = standardizeDatetime(data, datetimeColumn);
    }

    // 5. 文本标准化
    if (!textField.empty()) {
        data = textStandardization(data, textField);
    }

    // 6. 特征缩放
    if (!numericFields.empty()) {
        data = featureScaling(data, numericFields);
    }

    return data;
}

// 示例用法
int main() {
    // 设置预处理参数
    string input_file = "data.csv";       // 输入文件路径
    string output_file = "cleaned_data.csv"; // 输出文件路径

    char delimiter = ',';                 // 分隔符
    string encoding = "UTF-8";            // 编码格式

    string datetime_col = "date_time";    // 时间列名
    string text_col = "description";      // 文本列名

    vector<string> numeric_cols = {"value1", "value2", "value3"}; // 数值列名列表
    string strategy = "mean";             // 缺失值处理策略

    // 执行预处理
    vector<DataRow> processedData = dataPreprocessingPipeline(
        input_file,
        delimiter,
        encoding,
        datetime_col,
        text_col,
        numeric_cols,
        strategy
    );

    // 保存处理后的数据
    if (!processedData.empty()) {
        bool saved = saveProcessedData(processedData, output_file);
        if (saved) {
            cout << "数据预处理完成，已保存到 " << output_file << endl;
        } else {
            cerr << "数据保存失败" << endl;
        }
    } else {
        cerr << "预处理后数据为空" << endl;
    }

    return 0;
}
```

## 代码整体逻辑说明

这段C++代码实现了一个完整的数据预处理流程，主要包括以下几个步骤：

1. **数据加载**：从CSV文件中读取数据
2. **去重处理**：移除重复的行
3. **缺失值处理**：根据指定的策略处理缺失值
4. **时间格式统一**：将多种格式的时间数据转换为标准格式
5. **文本标准化**：清理文本数据，包括去除特殊符号和分词
6. **特征缩放**：对数值特征进行最小-最大缩放

## 关键知识点解释

1. **数据结构**：
   - 使用`DataRow`结构体存储每一行数据，内部使用`map`存储字段名和字段值的映射
   - 使用`vector<DataRow>`存储整个数据集

2. **数据去重**：
   - 将每行数据转换为字符串向量进行比较
   - 使用`std::set`存储已处理过的行

3. **缺失值处理**：
   - 根据不同的策略处理缺失值
   - 简化版中只实现了用0填充或删除字段

4. **时间格式统一**：
   - 使用Boost.DateTime库解析和处理日期时间
   - 尝试多种格式解析，如果失败则保留原始值

5. **文本标准化**：
   - 将文本转换为小写
   - 去除非字母数字字符
   - 使用Boost.Tokenizer进行分词

6. **特征缩放**：
   - 计算每个数值字段的最小值和最大值
   - 使用最小-最大缩放方法将数据缩放到[0,1]区间

## 优化建议

1. **错误处理**：增加更多的错误处理机制，例如文件不存在、列名不存在等情况

2. **性能优化**：对于大型数据集，可以考虑使用并行处理技术

3. **数据验证**：在预处理前添加数据验证步骤，确保数据质量

4. **日志记录**：添加日志记录功能，便于调试和追踪

5. **配置文件**：将参数配置移到外部配置文件中，提高代码的灵活性

6. **Boost库依赖**：此代码依赖于Boost库，确保在使用前已安装Boost库

注意：此代码是C++实现的数据预处理功能，与Python版本的功能对应，但实现方式有所不同。由于C++不是主要的数据分析语言，某些功能（如jieba分词）的实现较为简化。在实际应用中，可能需要根据具体需求进行调整和优化。

# C++ 数据清洗与预处理代码（带详细注释）

以下是使用C++实现的数据清洗与预处理代码，包括去重、缺失值处理、时间格式统一、文本标准化等功能，并为每个函数添加了详细注释：

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <cctype>
#include <locale>
#include <iomanip>
#include <regex>
#include <boost/algorithm/string.hpp>
#include <boost/date_time/posix_time/posix_time.hpp>
#include <boost/tokenizer.hpp>
#include <cmath>

using namespace std;
using namespace boost::posix_time;
using namespace boost::gregorian;
using namespace boost::algorithm;

// 结构体定义：数据行
struct DataRow {
    map<string, string> fields; // 使用map存储字段名和字段值的映射
};

// 1. 数据加载函数：从CSV文件中读取数据
vector<DataRow> loadData(const string& filePath, char delimiter = ',', const string& encoding = "UTF-8") {
    vector<DataRow> data;
    ifstream file(filePath); // 打开文件

    if (!file.is_open()) { // 检查文件是否打开成功
        cerr << "文件打开失败: " << filePath << endl;
        return data;
    }

    string line;
    while (getline(file, line)) { // 逐行读取文件
        DataRow row;
        stringstream ss(line); // 将行内容转换为字符串流
        string field;

        while (getline(ss, field, delimiter)) { // 使用分隔符分割字段
            // 处理字段中的空格（移除前导空格）
            if (!field.empty() && field[0] == ' ') {
                field.erase(0, 1);
            }
            // 将字段添加到行中（这里简化处理，实际应用中可能需要更复杂的处理）
            row.fields[field] = field;
        }
        data.push_back(row); // 将处理后的行添加到数据集中
    }

    return data;
}

// 2. 数据去重函数：移除重复的行
vector<DataRow> removeDuplicates(const vector<DataRow>& data) {
    set<vector<string>> seen; // 使用set存储已见过的行（将每行转换为字符串向量）
    vector<DataRow> uniqueData;

    for (const auto& row : data) {
        vector<string> rowVec;
        for (const auto& pair : row.fields) {
            rowVec.push_back(pair.second); // 将行中的每个字段值添加到向量中
        }
        // 检查该行是否已经见过
        if (seen.find(rowVec) == seen.end()) {
            seen.insert(rowVec); // 如果是新行，将其添加到已见过的集合中
            uniqueData.push_back(row); // 将新行添加到结果数据集中
        }
    }

    return uniqueData;
}

// 3. 缺失值处理函数：处理数据中的缺失值
vector<DataRow> handleMissingValues(vector<DataRow>& data, const string& strategy) {
    // 简化版：用空字符串填充缺失值
    for (auto& row : data) { // 遍历每一行
        for (auto& field : row.fields) { // 遍历行中的每个字段
            if (field.second.empty()) { // 检查字段值是否为空（表示缺失值）
                if (strategy == "mean" || strategy == "median" || strategy == "mode") {
                    // 这里只是示例，实际实现需要根据数据类型处理
                    // 对于数值型数据，应该使用均值、中位数或众数填充
                    field.second = "0";
                } else if (strategy == "drop") {
                    // 删除缺失值所在的列
                    row.fields.erase(field.first);
                }
            }
        }
    }
    return data;
}

// 4. 时间格式统一函数：将多种格式的时间数据转换为标准格式
vector<DataRow> standardizeDatetime(vector<DataRow>& data, const string& datetimeField) {
    // 简化版：假设时间格式为YYYY-MM-DD HH:MM:SS
    for (auto& row : data) {
        if (row.fields.find(datetimeField) != row.fields.end()) { // 检查行中是否存在指定的时间字段
            string original = row[datetimeField];
            try {
                // 尝试解析标准格式：YYYY-MM-DD HH:MM:SS
                // 这里使用Boost.DateTime库进行时间解析（需要链接Boost.DateTime库）
                // 注意：以下代码是简化示例，实际实现需要更复杂的日期时间解析逻辑

                // 将时间字符串分割为各个部分
                // 这里使用Boost.Tokenizer进行分词
                boost::char_separator<char> cs("-");
                boost::tokenizer<boost::char_separator<char>> tokens1(original, cs);
                string year = *tokens1.begin();
                string month = *(tokens1.begin()+1);
                string day = *(tokens1.begin()+2);

                cs = " ";
                tokenizer<cs> tokens2(*(tokens1.end()), cs); // 继续分割剩余部分
                string hour = *tokens2.begin();
                string minute = *(tokens2.begin()+1);
                string second = *(tokens2.end()-1); // 假设最后一个是秒

                // 创建日期对象
                date d(
                    year_to_yd(stoi(year), stoi(month), stoi(day)), // 将年月日转换为儒略日
                    stoj(month), // 月份
                    stoj(day) // 日
                );

                // 创建时间对象
                time_duration td(
                    hours(stoi(hour)) + minutes(stoi(minute)) + seconds(stoi(second))
                );

                // 创建完整的时间对象
                local_date_time dt(d, td); // 日期和时间
                local_date_time dt_end(d, hours(23) + minutes(59) + seconds(59)); // 当天结束时间

                // 将处理后的时间格式存储为字符串
                string formatted = year + "-" + month + "-" + day + " " + hour + ":" + minute + ":" + second;
                row[datetimeField] = formatted;
            } catch (...) {
                // 如果解析失败，尝试其他方法
                try {
                    // 使用Boost.DateTime解析（另一种方法）
                    local_date_time dt = from_iso_string(original); // 尝试从ISO格式字符串解析
                    ostringstream oss;
                    oss << dt; // 将时间对象转换为字符串
                    row[datetimeField] = oss.str(); // 存储格式化后的时间字符串
                } catch (...) {
                    // 解析失败，保留原始值
                    cout << "无法解析时间: " << original << endl;
                }
            }
        }
    }
    return data;
}

// 5. 文本标准化函数：清理文本数据，包括去除特殊符号、分词等操作
vector<DataRow> textStandardization(vector<DataRow>& data, const string& textField) {
    // 简化版：只进行分词处理
    for (auto& row : data) {
        if (row.fields.find(textField) != row.fields.end()) { // 检查行中是否存在指定的文本字段
            string text = row[textField];
            // 转换为小写（标准化文本大小写）
            for (char& c : text) {
                c = tolower(c); // 将字符转换为小写
            }
            // 去除特殊符号（保留字母、数字和空格）
            text.erase(remove_if(text.begin(), text.end(), [](unsigned char c) {
                return !isalnum(c) && c != ' '; // 移除非字母数字且不是空格的字符
            }), text.end());

            // 分词（使用空格分隔）
            boost::char_separator<char> cs(" ,.!?;:"); // 定义分隔符
            boost::tokenizer<boost::char_separator<char>> tokens(text, cs); // 使用分隔符进行分词

            // 将分词结果组合成字符串（用空格分隔）
            string tokenized;
            for (const string& token : tokens) {
                if (!token.empty()) { // 跳过空字符串
                    if (!tokenized.empty()) { // 如果不是第一个词
                        tokenized += " "; // 添加空格
                    }
                    tokenized += token; // 添加词
                }
            }

            row[textField] = tokenized; // 存储处理后的文本
        }
    }
    return data;
}

// 6. 特征缩放函数：对数值特征进行标准化处理
vector<DataRow> featureScaling(vector<DataRow>& data, const vector<string>& numericFields) {
    // 简化版：只对数值字段进行最小-最大缩放

    // 1. 收集每个字段的最小值和最大值
    map<string, pair<double, double>> fieldRanges;

    for (auto& row : data) {
        for (const string& field : numericFields) {
            if (row.fields.find(field) != row.fields.end()) { // 检查字段是否存在
                try {
                    double value = stod(row[field]); // 尝试将字段值转换为双精度浮点数

                    // 2. 更新该字段的最小值和最大值
                    if (fieldRanges.find(field) == fieldRanges.end()) { // 如果是该字段的第一个值
                        fieldRanges[field] = make_pair(value, value); // 初始化最小值和最大值
                    } else {
                        if (value < fieldRanges[field].first) { // 如果新值小于当前最小值
                            fieldRanges[field].first = value; // 更新最小值
                        }
                        if (value > fieldRanges[field].second) { // 如果新值大于当前最大值
                            fieldRanges[field].second = value; // 更新最大值
                        }
                    }
                } catch (...) {
                    // 转换失败，跳过该字段值
                    continue;
                }
            }
        }
    }

    // 3. 应用最小-最大缩放
    for (auto& row : data) {
        for (const string& field : numericFields) {
            if (row.fields.find(field) != row.fields.end()) { // 检查字段是否存在
                try {
                    double value = stod(row[field]); // 尝试将字段值转换为双精度浮点数

                    // 4. 获取该字段的最小值和最大值
                    double minVal = fieldRanges[field].first;
                    double maxVal = fieldRanges[field].second;

                    // 5. 应用最小-最大缩放公式：(value - minVal) / (maxVal - minVal)
                    double scaledValue = (value - minVal) / (maxVal - minVal);

                    // 6. 将缩放后的值存回字段
                    row[field] = to_string(scaledValue); // 转换为字符串存储
                } catch (...) {
                    // 转换失败，保留原值
                    continue;
                }
            }
        }
    }

    return data;
}

// 辅助函数：获取DataRow的字段值
string& operator[](DataRow& row, const string& key) {
    return row.fields[key];
}

// 辅助函数：保存处理后的数据到CSV文件
bool saveProcessedData(const vector<DataRow>& data, const string& outputPath) {
    ofstream file(outputPath); // 打开文件进行写入

    if (!file.is_open()) { // 检查文件是否打开成功
        cerr << "无法打开文件保存: " << outputPath << endl;
        return false;
    }

    // 写入表头（简化版）
    if (!data.empty()) {
        // 实际应用中应使用实际表头，这里用占位符
        file << "header1,header2,header3\n";

        // 写入数据行
        for (const auto& row : data) {
            for (const auto& pair : row.fields) {
                file << "\"" << pair.second << "\",";
            }
            file << "\n";
        }
    }

    file.close(); // 关闭文件
    return true;
}

// 主函数：执行完整的数据预处理流程
vector<DataRow> dataPreprocessingPipeline(
    const string& filePath, // 输入文件路径
    char delimiter,         // 分隔符
    const string& encoding, // 编码格式
    const string& datetimeColumn, // 时间列名
    const string& textField, // 文本列名
    const vector<string>& numericFields, // 数值列名列表
    const string& strategy   // 缺失值处理策略
) {
    // 1. 加载数据
    vector<DataRow> data = loadData(filePath, delimiter, encoding);
    if (data.empty()) {
        cerr << "加载数据失败，数据集为空" << endl;
        return data;
    }

    // 2. 去重
    data = removeDuplicates(data);
    cout << "去重后数据集大小: " << data.size() << endl;

    // 3. 处理缺失值
    data = handleMissingValues(data, strategy);
    cout << "缺失值处理完成" << endl;

    // 4. 统一时间格式
    if (!datetimeColumn.empty()) {
        data = standardizeDatetime(data, datetimeColumn);
        cout << "时间格式统一完成" << endl;
    }

    // 5. 文本标准化
    if (!textField.empty()) {
        data = textStandardization(data, textField);
        cout << "文本标准化完成" << endl;
    }

    // 6. 特征缩放
    if (!numericFields.empty()) {
        data = featureScaling(data, numericFields);
        cout << "特征缩放完成" << endl;
    }

    return data;
}

// 示例用法
int main() {
    // 设置预处理参数
    string input_file = "data.csv";       // 输入文件路径
    string output_file = "cleaned_data.csv"; // 输出文件路径

    char delimiter = ',';                 // 分隔符
    string encoding = "UTF-8";            // 编码格式

    string datetime_col = "date_time";    // 时间列名
    string text_col = "description";      // 文本列名

    vector<string> numeric_cols = {"value1", "value2", "value3"}; // 数值列名列表
    string strategy = "mean";             // 缺失值处理策略

    // 执行预处理
    vector<DataRow> processedData = dataPreprocessingPipeline(
        input_file,
        delimiter,
        encoding,
        datetime_col,
        text_col,
        numeric_cols,
        strategy
    );

    // 保存处理后的数据
    if (!processedData.empty()) {
        bool saved = saveProcessedData(processedData, output_file);
        if (saved) {
            cout << "数据预处理完成，已保存到 " << output_file << endl;
        } else {
            cerr << "数据保存失败" << endl;
        }
    } else {
        cerr << "预处理后数据为空" << endl;
    }

    return 0;
}
```

## 代码详细注释说明

### 1. 数据加载函数 (loadData)
