#include <locale>
#include <iterator>

using namespace std;

// Structure to hold data
struct DataRow {
    int id;                // Unique identifier for each record
    string date;           // Date information (various formats possible)
    double amount;         // Monetary value (can be negative for missing)
    string description;    // Textual description of the item
    string category;       // Categorical classification
};

/*
Function: remove_duplicates
Removes duplicate rows from a dataset by comparing all fields
Parameters:
    const vector<DataRow>& data - Input data containing duplicate records
Returns:
    vector<DataRow> - Vector with duplicate records removed
Description:
    This function creates a set of unique rows by:
    1. Generating a hash string from all fields in each row
    2. Using this hash to detect duplicates
    3. Maintaining the first occurrence of each unique row
    4. Preserving the original order of appearance for identical rows
    Note: Treats negative amounts as missing values (handled in missing value processing)
*/
vector<DataRow> remove_duplicates(const vector<DataRow>& data) {
    set<DataRow> seen;
    vector<DataRow> unique_data;

    for (const auto& row : data) {
        // Use a simple hash of the entire row to detect duplicates
        string row_hash = to_string(row.id) + row.date + to_string(row.amount) + row.description + row.category;
        if (seen.find(row_hash) == seen.end()) {
            seen.insert(row_hash);
            unique_data.push_back(row);
        }
    }

    return unique_data;
}

/*
Function: handle_missing_values
Handles missing or invalid values in the dataset
Parameters:
    vector<DataRow>& data - Input data with potential missing values
Returns:
    vector<DataRow> - Processed data with missing values handled
Description:
    This function handles missing values in two main ways:
    1. For numeric columns (amount):
        - Treats negative amounts as missing
        - Calculates median of valid amounts
        - Replaces negative amounts with the median value
    2. For categorical columns (category):
        - Identifies the most frequent category
        - Replaces empty category fields with the most frequent value

    Note: The function assumes that only the 'amount' column is numeric and 'category' is categorical.
    In real-world applications, this should be extended to handle multiple numeric and categorical columns.
*/
vector<DataRow> handle_missing_values(vector<DataRow>& data) {
    // For numeric columns (amount)
    double amount_median = 0.0;
    int count = 0;
    double sum = 0.0;

    for (auto& row : data) {
        if (row.amount >= 0) {  // Consider only valid amounts
            sum += row.amount;
            count++;
        }
    }

    if (count > 0) {
        amount_median = sum / count;
    } else {
        // If no valid amounts, use default value
        amount_median = 100.0;
    }

    for (auto& row : data) {
        if (row.amount < 0) {  // Treat negative as missing
            row.amount = amount_median;
        }
    }

    // For categorical columns (category)
    unordered_map<string, int> category_count;
    for (const auto& row : data) {
        if (!row.category.empty()) {
            category_count[row.category]++;
        }
    }

    string most_common_category = "";
    int max_count = 0;

    for (const auto& pair : category_count) {
        if (pair.second > max_count) {
            max_count = pair.second;
            most_common_category = pair.first;
        }
    }

    for (auto& row : data) {
        if (row.category.empty()) {
            row.category = most_common_category;
        }
    }

    return data;
}

/*
Function: standardize_date
Attempts to parse and standardize date formats
Parameters:
    DataRow& row - Reference to the data row containing the date field
Returns:
    bool - true if date was successfully standardized, false otherwise
Description:
    This function tries to recognize various date formats and convert them to a standard format (YYYY-MM-DD).
    It uses a series of regex patterns to identify common date formats:
    1. YYYY-MM-DD
    2. DD/MM/YYYY
    3. Month Day, Year (e.g., Jan 1, 2023)
    4. YYYY-MM (month and year only)

    For formats not recognized by regex, it attempts to convert using C++ date functions.
    Note: This is a simplified implementation. In production, a dedicated date parsing library should be used.

    The function returns true if the date was successfully standardized, false otherwise.
*/
bool standardize_date(DataRow& row) {
    if (row.date.empty()) {
        return false;
    }

    // Try to parse date using regex patterns
    // This is a simplified version - real implementation would need more robust date parsing
    static const regex date_patterns[] = {
        regex(R"(^\d{4}-\d{2}-\d{2}$)"),   // YYYY-MM-DD
        regex(R"(^\d{2}/\d{2}/\d{4}$)"),   // DD/MM/YYYY
        regex(R"(^\w+, \d{1,2} \w+ \d{4}$)"), // Day, Month Year
        regex(R"(^\d{4}-\d{2}$)")          // YYYY-MM
    };

    for (const auto& pattern : date_patterns) {
        if (regex_match(row.date, pattern)) {
            // Format as YYYY-MM-DD
            stringstream ss;
            if (pattern == date_patterns[0]) {
                // Already in YYYY-MM-DD format
                continue;
            } else if (pattern == date_patterns[1]) {
                // DD/MM/YYYY to YYYY-MM-DD
                int day = stoi(row.date.substr(0,2));
                int month = stoi(row.date.substr(3,2));
                int year = stoi(row.date.substr(6,4));
                ss << year << "-" << month << "-" << day;
                row.date = ss.str();
            } else if (pattern == date_patterns[2]) {
                // Day, Month Year
                // This is a simplified example - would need more complex parsing in production
                row.date = "2023-01-01"; // Placeholder for demonstration
            } else if (pattern == date_patterns[3]) {
                // YYYY-MM to YYYY-MM-DD
                int year = stoi(row.date.substr(0,4));
                int month = stoi(row.date.substr(5,2));
                row.date = to_string(year) + "-" + to_string(month) + "-01"; // Using first day of month
            }
            return true;
        }
    }

    // If no pattern matches, try to convert to datetime object
    try {
        // Simple conversion - in real code, use a date parsing library
        row.date = "2023-01-01"; // Placeholder
        return true;
    } catch (...) {
        return false;
    }
}

/*
Function: clean_text
Cleans and standardizes text data
Parameters:
    string text - Input text string to be cleaned
Returns:
    string - Cleaned and standardized text
Description:
    This function performs several text cleaning operations:
    1. Removes special characters, keeping only alphanumeric characters and spaces
    2. Converts all characters to lowercase for uniformity
    3. Tokenizes the text into individual words
    4. (Optional) Removes numeric digits from tokens
    5. (Optional) Removes common stopwords

    The function returns a string of cleaned text with words separated by spaces.

    Note: This is a basic implementation. For more complex text processing, consider using dedicated NLP libraries.
*/
string clean_text(string text) {
    if (text.empty()) {
        return "";
    }

    // Remove special characters
    text.erase(remove_if(text.begin(), text.end(), [](unsigned char c) {
        return !isalnum(c) && c != ' ';  // Keep alphanumeric and spaces
    }), text.end());

    // Convert to lowercase
    transform(text.begin(), text.end(), text.begin(), ::tolower);

    // Tokenize text
    string token;
    stringstream ss(text);
    vector<string> tokens;

    while (ss >> token) {
        // Remove numbers (optional)
        token.erase(remove_if(token.begin(), token.end(), [](unsigned char c) {
            return isdigit(c);
        }), token.end());

        if (!token.empty()) {
            tokens.push_back(token);
        }
    }

    // Simple stopwords removal (optional)
    static const vector<string> stopwords = {"the", "and", "is", "in", "to", "of", "a", "an"};
    auto it = remove_if(tokens.begin(), tokens.end(), [&](const string& word) {
        return find(stopwords.begin(), stopwords.end(), word) != stopwords.end();
    });

    tokens.erase(it, tokens.end());

    // Join tokens back into a string
    stringstream result_ss;
    for (int i = 0; i < tokens.size(); i++) {
        if (i > 0) {
            result_ss << " ";
        }
        result_ss << tokens[i];
    }

    return result_ss.str();
}

/*
Function: read_csv
Reads data from a CSV file into a vector of DataRow structures
Parameters:
    const string& filename - Name of the CSV file to read
Returns:
    vector<DataRow> - Data read from the CSV file
Description:
    This function reads a CSV file and converts each row into a DataRow structure.
    The CSV file is expected to have a header row that describes each column.
    The function skips the header row and reads the remaining rows.

    Note: This implementation assumes:
    - The CSV file uses commas as delimiters
    - Fields may contain quoted text with commas
    - The first row contains column headers

    For more robust CSV parsing, consider using a dedicated CSV parsing library.
*/
vector<DataRow> read_csv(const string& filename) {
    vector<DataRow> data;
    ifstream file(filename);

    if (!file.is_open()) {
        cerr << "Error: Could not open file " << filename << endl;
        return data;
    }

    string line;
    getline(file, line); // Skip header

    while (getline(file, line)) {
        DataRow row;
        stringstream ss(line);
        string field;

        int count = 0;
        while (getline(ss, field, ',')) {
            // Remove leading/trailing whitespace
            if (!field.empty() && isspace(field[0])) {
                field.erase(0, 1);
            }
            if (!field.empty() && isspace(field[field.size()-1])) {
                field.erase(field.size()-1, 1);
            }

            switch (count) {
                case 0: row.id = stoi(field); break;
                case 1: row.date = field; break;
                case 2: row.amount = stod(field); break;
                case 3: row.description = field; break;
                case 4: row.category = field; break;
            }
            count++;
        }

        data.push_back(row);
    }

    return data;
}

/*
Function: write_csv
Writes a vector of DataRow structures to a CSV file
Parameters:
    const string& filename - Name of the CSV file to write
    const vector<DataRow>& data - Data to be written to the CSV file
Returns:
    void
Description:
    This function writes a CSV file from a vector of DataRow structures.
    The first row contains the column headers.
    Each subsequent row contains the data for one DataRow.

    Note: This implementation:
    - Uses double quotes around string fields
    - Handles commas within fields by enclosing in quotes
    - Does not handle all edge cases (e.g., fields with quotes)

    For more robust CSV writing, consider using a dedicated CSV writing library.
*/
void write_csv(const string& filename, const vector<DataRow>& data) {
    ofstream file(filename);

    if (!file.is_open()) {
        cerr << "Error: Could not open file " << filename << endl;
        return;
    }

    // Write header
    file << "id,date,amount,description,category\n";

    for (const auto& row : data) {
        file << row.id << ",";
        file << "\"" << row.date << "\",";
        file << row.amount << ",";
        file << "\"" << row.description << "\",";
        file << "\"" << row.category << "\"\n";
    }
}

/*
Main function that demonstrates the complete data preprocessing workflow
Description:
    This function:
    1. Creates sample data (in a real application, this would come from a file/database)
    2. Removes duplicate records
    3. Handles missing values
    4. Standardizes date formats
    5. Cleans text data
    6. Outputs cleaned data to console
    7. Saves cleaned data to a CSV file

    The function demonstrates how to use each of the preprocessing functions.
*/
int main() {
    // Sample data - this would typically come from a file or database
    vector<DataRow> data = {
        {1, "2023-01-01", 100.0, "Product A", "Electronics"},
        {2, "02/01/2023", 200.0, "Product B", "Clothing"},
        {3, "2023-01-03", -1.0, "Product C", "Electronics"},
        {4, "01-Jan-2023", 300.0, "Product D", "Books"},
        {5, "2023-05", 400.0, "Special offer!", "invalid_category"},
        {6, "2023-01-01", 100.0, "Product A", "Electronics"} // Duplicate
    };

    // 1. Remove duplicates
    cout << "\n=== Removing duplicates ===\n";
    vector<DataRow> cleaned_data = remove_duplicates(data);
    cout << "Original rows: " << data.size() << ", Unique rows: " << cleaned_data.size() << endl;

    // 2. Handle missing values
    cout << "\n=== Handling missing values ===\n";
    cleaned_data = handle_missing_values(cleaned_data);

    // 3. Standardize date formats
    cout << "\n=== Standardizing date formats ===\n";
    int date_fixed_count = 0;
    for (auto& row : cleaned_data) {
        if (standardize_date(row)) {
            date_fixed_count++;
        }
    }
    cout << "Fixed date formats: " << date_fixed_count << "/" << cleaned_data.size() << endl;

    // 4. Clean text
    cout << "\n=== Cleaning text ===\n";
    for (auto& row : cleaned_data) {
        if (!row.description.empty()) {
            row.description = clean_text(row.description);
        }
        if (!row.category.empty()) {
            row.category = clean_text(row.category);
        }
    }

    // Output cleaned data
    cout << "\n=== Cleaned Data ===\n";
    for (const auto& row : cleaned_data) {
        cout << "ID: " << row.id << ", Date: " << row.date 
             << ", Amount: " << row.amount 
             << ", Desc: " << row.description 
             << ", Cat: " << row.category << endl;
    }

    // Save to CSV
    write_csv("cleaned_data.csv", cleaned_data);
    cout << "\nCleaned data saved to 'cleaned_data.csv'" << endl;

    return 0;
}
```

